import { useEffect, useMemo } from 'react';
import { useParams, Link } from 'react-router-dom';
import Navbar from '@/components/feature/Navbar';
import Footer from '@/components/feature/Footer';
import Breadcrumb from '@/components/base/Breadcrumb';
import { movies, articles } from '@/mocks/movies';

export default function ArticlePage() {
  const { slug } = useParams<{ slug: string }>();

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [slug]);

  const movie = useMemo(() => movies.find((m) => m.slug === slug), [slug]);
  const article = useMemo(() => articles.find((a) => a.slug === slug), [slug]);

  const relatedMovies = useMemo(() => {
    if (!movie) return [];
    return movies
      .filter((m) => m.category === movie.category && m.id !== movie.id)
      .slice(0, 4);
  }, [movie]);

  const relatedArticles = useMemo(() => {
    if (!article) return [];
    return articles.filter((a) => a.id !== article.id).slice(0, 4);
  }, [article]);

  if (!movie && !article) {
    return (
      <>
        <Navbar />
        <main className="pt-16">
          <div className="flex flex-col items-center justify-center py-32 px-4">
            <div className="w-16 h-16 flex items-center justify-center mb-4">
              <i className="ri-error-warning-line text-4xl text-foreground-300"></i>
            </div>
            <h1 className="text-xl font-heading font-bold text-foreground-900 mb-2">内容不存在</h1>
            <p className="text-sm text-foreground-500 mb-6">该页面可能已被移除或链接无效</p>
            <Link
              to="/"
              className="px-6 py-2.5 bg-primary-500 text-background-50 rounded-full text-sm font-medium hover:bg-primary-600 transition-colors duration-200 whitespace-nowrap cursor-pointer"
              onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
            >
              返回首页
            </Link>
          </div>
        </main>
        <Footer />
      </>
    );
  }

  if (movie) {
    return (
      <>
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify({
              '@context': 'https://schema.org',
              '@type': 'Movie',
              name: movie.title,
              description: movie.description,
              dateCreated: movie.year,
              countryOfOrigin: movie.region,
              genre: movie.type,
              url: `https://jointmove.github.io/article/${movie.slug}`,
            }),
          }}
        />

        <Navbar />
        <main className="pt-16">
          <div className="bg-background-50">
            <div className="max-w-7xl mx-auto">
              <Breadcrumb
                items={[
                  { label: '首页', path: '/' },
                  { label: categoryLabelMap[movie.category] || '全部', path: `/category/${movie.category}` },
                  { label: movie.title },
                ]}
              />
            </div>
          </div>

          <section className="w-full px-4 md:px-6 py-10 bg-background-50">
            <div className="max-w-5xl mx-auto">
              <div className="flex flex-col md:flex-row gap-8">
                <div className="w-full md:w-64 shrink-0">
                  <div className="rounded-xl overflow-hidden aspect-[2/3] sticky top-24">
                    <img
                      src={movie.poster}
                      alt={movie.title}
                      className="w-full h-full object-cover object-top"
                    />
                  </div>
                </div>

                <div className="flex-1">
                  <h1 className="text-2xl md:text-3xl font-heading font-bold text-foreground-900 mb-4">
                    {movie.title}
                  </h1>

                  <div className="flex flex-wrap items-center gap-3 mb-5">
                    {movie.tags.map((tag) => (
                      <span key={tag} className="px-3 py-1 bg-primary-100 text-primary-700 text-xs rounded-md font-medium">
                        {tag}
                      </span>
                    ))}
                    <span className="px-3 py-1 bg-accent-100 text-accent-800 text-xs rounded-md font-bold">
                      {movie.rating} 分
                    </span>
                  </div>

                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-6">
                    {[
                      { label: '类型', value: movie.type },
                      { label: '地区', value: movie.region },
                      { label: '年份', value: movie.year },
                      { label: '时长', value: movie.duration },
                      { label: '更新日期', value: movie.updateDate },
                    ].map((info) => (
                      <div key={info.label} className="bg-background-100 rounded-lg px-4 py-3">
                        <div className="text-xs text-foreground-500 mb-0.5">{info.label}</div>
                        <div className="text-sm font-medium text-foreground-800">{info.value}</div>
                      </div>
                    ))}
                  </div>

                  <div className="mb-6">
                    <h3 className="text-base font-heading font-bold text-foreground-900 mb-3">剧情简介</h3>
                    <p className="text-sm text-foreground-600 leading-relaxed">{movie.description}</p>
                  </div>
                </div>
              </div>
            </div>
          </section>

          {relatedMovies.length > 0 && (
            <section className="w-full px-4 md:px-6 py-12 bg-background-100">
              <div className="max-w-5xl mx-auto">
                <h2 className="text-xl font-heading font-bold text-foreground-900 mb-6">相关推荐</h2>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                  {relatedMovies.map((m) => (
                    <Link
                      key={m.id}
                      to={`/article/${m.slug}`}
                      className="group cursor-pointer"
                      onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                    >
                      <div className="relative rounded-xl overflow-hidden aspect-[3/4] mb-3">
                        <img
                          src={m.poster}
                          alt={m.title}
                          className="w-full h-full object-cover object-top group-hover:scale-105 transition-transform duration-500"
                        />
                        <div className="absolute top-2 right-2">
                          <span className="px-2 py-0.5 bg-background-950/70 text-accent-400 text-xs rounded-md font-bold">
                            {m.rating}
                          </span>
                        </div>
                      </div>
                      <h3 className="text-sm font-medium text-foreground-900 group-hover:text-primary-600 transition-colors duration-200 line-clamp-1">
                        {m.title}
                      </h3>
                    </Link>
                  ))}
                </div>
              </div>
            </section>
          )}
        </main>
        <Footer />
      </>
    );
  }

  if (article) {
    const paragraphs = article.content.split('\n\n').filter(Boolean);

    return (
      <>
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify({
              '@context': 'https://schema.org',
              '@type': 'Article',
              headline: article.title,
              description: article.summary,
              author: { '@type': 'Person', name: article.author },
              datePublished: article.date,
              url: `https://jointmove.github.io/article/${article.slug}`,
            }),
          }}
        />

        <Navbar />
        <main className="pt-16">
          <div className="bg-background-50">
            <div className="max-w-7xl mx-auto">
              <Breadcrumb
                items={[
                  { label: '首页', path: '/' },
                  { label: '影视资讯', path: '/category/all' },
                  { label: article.title },
                ]}
              />
            </div>
          </div>

          <article className="w-full px-4 md:px-6 py-10 bg-background-50">
            <div className="max-w-4xl mx-auto">
              <div className="mb-6">
                <span className="px-3 py-1 bg-primary-100 text-primary-700 text-xs rounded-md font-medium">
                  {article.category}
                </span>
              </div>

              <h1 className="text-2xl md:text-3xl font-heading font-bold text-foreground-900 mb-4 leading-tight">
                {article.title}
              </h1>

              <div className="flex flex-wrap items-center gap-4 text-sm text-foreground-500 mb-8 pb-8 border-b border-background-200">
                <span>{article.author}</span>
                <span>{article.date}</span>
                <span>{article.readCount.toLocaleString()} 阅读</span>
              </div>

              <div className="mb-8 rounded-xl overflow-hidden">
                <img
                  src={article.cover}
                  alt={article.title}
                  className="w-full aspect-[2/1] object-cover"
                />
              </div>

              <div className="prose-custom text-foreground-700 leading-relaxed">
                {paragraphs.map((p, i) => {
                  const isHeading = p.startsWith('【') && p.includes('】');
                  if (isHeading) {
                    const match = p.match(/【(.+?)】/);
                    const title = match ? match[1] : '';
                    const rest = p.replace(/【.+?】/, '').trim();
                    return (
                      <div key={i} className="mb-6">
                        <h2 className="text-lg font-heading font-bold text-foreground-900 mb-3">{title}</h2>
                        {rest && <p className="text-sm text-foreground-600 leading-relaxed">{rest}</p>}
                      </div>
                    );
                  }
                  return (
                    <p key={i} className="text-sm text-foreground-600 leading-relaxed mb-4">
                      {p.trim()}
                    </p>
                  );
                })}
              </div>

              <div className="flex flex-wrap gap-2 mt-8 pt-6 border-t border-background-200">
                {article.tags.map((tag) => (
                  <span key={tag} className="px-3 py-1.5 bg-background-100 text-foreground-600 text-xs rounded-full">
                    #{tag}
                  </span>
                ))}
              </div>
            </div>
          </article>

          {relatedArticles.length > 0 && (
            <section className="w-full px-4 md:px-6 py-12 bg-background-100">
              <div className="max-w-4xl mx-auto">
                <h2 className="text-xl font-heading font-bold text-foreground-900 mb-6">相关文章</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  {relatedArticles.map((a) => (
                    <Link
                      key={a.id}
                      to={`/article/${a.slug}`}
                      className="group cursor-pointer bg-background-50 rounded-xl overflow-hidden"
                      onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                    >
                      <div className="flex gap-4 p-4">
                        <div className="w-24 h-24 rounded-lg overflow-hidden shrink-0">
                          <img
                            src={a.cover}
                            alt={a.title}
                            className="w-full h-full object-cover"
                          />
                        </div>
                        <div className="flex-1 min-w-0">
                          <span className="text-xs text-primary-600 font-medium">{a.category}</span>
                          <h3 className="text-sm font-medium text-foreground-900 group-hover:text-primary-600 transition-colors duration-200 line-clamp-2 mt-1">
                            {a.title}
                          </h3>
                          <div className="flex items-center gap-2 mt-2 text-xs text-foreground-400">
                            <span>{a.date}</span>
                            <span>{a.readCount.toLocaleString()} 阅读</span>
                          </div>
                        </div>
                      </div>
                    </Link>
                  ))}
                </div>
              </div>
            </section>
          )}
        </main>
        <Footer />
      </>
    );
  }

  return null;
}

const categoryLabelMap: Record<string, string> = {
  movie: '电影',
  tv: '电视剧',
  variety: '综艺',
  anime: '动漫',
};